import{_ as r,C as n,o as a,c as d,j as t,a as o,E as i,a2 as l}from"./chunks/framework.BxGh02fV.js";const w=JSON.parse('{"title":"Modules","description":"","frontmatter":{"title":"Modules"},"headers":[],"relativePath":"en/guide/modules.md","filePath":"en/guide/modules.md"}'),h={name:"en/guide/modules.md"};function u(g,e,c,f,m,p){const s=n("Capture");return a(),d("div",null,[e[0]||(e[0]=t("h1",{id:"modules",tabindex:"-1"},[o("Modules "),t("a",{class:"header-anchor",href:"#modules","aria-label":'Permalink to "Modules"'},"​")],-1)),e[1]||(e[1]=t("p",null,[o("This screen shows each module of your project — each stack declared in "),t("code",null,"effortless.json"),o(" — on its own card. Come here to see at a glance where each part of the code stands: its version, its repository, its delivery and the work that touched it.")],-1)),i(s,{name:"modules",alt:"The Modules screen: one card per module, with its identity, git and version, delivery and work"}),e[2]||(e[2]=l('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>At the top, the number of declared modules. Then one card per module, with its name, its path and badges: <strong>own repository</strong> (the module has its own git repository) or <strong>root repository</strong> (it lives in the project&#39;s), <strong>deliverable</strong> when a delivery is declared, <strong>folder missing</strong> when its path does not exist.</p><p>Each card has five blocks:</p><ul><li><strong>Identity</strong>: the <strong>Languages</strong>, the stack <strong>Model</strong> and the <strong>Standards</strong> present for this module.</li><li><strong>Git and version</strong>: the <strong>Version</strong> read from its files (<code>package.json</code>, otherwise <code>Cargo.toml</code>), the <strong>Branch</strong>, the number of <strong>Modified files</strong>, the <strong>Last tag</strong> and the <strong>Last commit</strong>.</li><li><strong>Delivery</strong>: the <strong>Build</strong> command and the <strong>Artifacts</strong> declared in the Delivery screen. Otherwise: &quot;No delivery declared for this module.&quot;</li><li><strong>Work (90 days)</strong>: the number of <strong>Commits</strong> that touched the module, the <strong>Epics · stories · tasks</strong> they cite, and the <strong>Recent epics</strong>.</li><li><strong>Builds</strong>: the module&#39;s <strong>Build volume</strong> at the last measurement, with its date (&quot;Never measured&quot; otherwise), the detail per build folder, and the <strong>Module debug info</strong> and <strong>Dependencies debug info</strong>. The volume is highlighted when it goes over the project threshold (10 GB by default, set with <code>settings.build_volume.threshold</code> in <code>effortless.json</code>).</li></ul><p>When a source could not be read — for instance a folder that is not a git repository — the card says so: &quot;A source could not be read&quot;, with the detail on hover. When git says nothing about the module, the Work block shows &quot;Nothing readable in git for this module.&quot; Nothing is hidden.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><p>The <strong>Builds</strong> block acts on the module&#39;s build folders — what compilation produces and can regenerate:</p><ul><li><strong>Measure</strong> walks the build folders: those the stack declares and those the build tool tagged as a cache. It counts the real disk usage, each file once. The measurement stays on your machine.</li><li><strong>Clean…</strong> first shows what will happen: the reset command declared by the language (for example <code>cargo clean</code>) and the size it will free. Nothing goes until you click <strong>Clean</strong>. The next build will be a full one.</li><li>The <strong>debug info</strong> selectors set how much debug information dev builds carry: <strong>none</strong>, <strong>lines only</strong> or <strong>full</strong>. The setting applies to the commands Effortless runs for this module, without rewriting any of your files. A scope the language cannot adjust shows &quot;not adjustable&quot;: for Rust, that is the case of dependencies, which stay without debug info.</li></ul><p>When a module goes over the threshold, the resume screen of the <a href="/Effortless/en/guide/dashboard.html">Dashboard</a> shows &quot;Heavy builds&quot; and leads here.</p><p>The rest of the screen is read-only. A module is declared through the <strong>Stack</strong> step of the <a href="/Effortless/en/guide/create.html">Creation assistant</a>, through <strong>Preferences</strong> › <strong>Stack model</strong> (<strong>Create the stack</strong>), or by an agent with <code>effortless_stack_add</code>. Its delivery is set on the <a href="/Effortless/en/guide/release.html">Delivery</a> screen.</p><h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p>An agent reads the same thing through the <code>effortless_modules</code> verb. The Builds block has its own verbs: <code>effortless_build_volume</code> (measure), <code>effortless_build_reset</code> (clean, simulation first) and <code>effortless_build_debug</code> (debug info) — see <a href="/Effortless/en/agent/code.html">Code and stacks</a>.</p>',12))])}const y=r(h,[["render",u]]);export{w as __pageData,y as default};
